async function insertKanbanData() {
    const formattedData = await Promise.all(kanbanData.map(async (data) => {
        const part = await prisma.part.findUnique({ where: { code: data.part_code } });
        const rack = await prisma.rack.findUnique({ where: { code: data.rack } });
        const machineArea = await prisma.machineArea.findUnique({ where: { name: data.area } });
        const machine = await prisma.machine.findUnique({ where: { code: data.mesin } });

        return {
            uom: data.uom,
            lead_time: data.lead_time,
            part_code: part ? part.code : null,
            rack_id: rack ? rack.id : null,
            machine_area_id: machineArea ? machineArea.id : null,
            machine_id: machine ? machine.id : null,
        };
    }));

    await prisma.kanban.createMany({ data: formattedData, skipDuplicates: true });

    console.log("Data kanban berhasil diinsert.");
}


main()
    .catch((e) => {
        console.error(e.message);
        process.exit(1);
    })
    .finally(async () => {
        await prisma.$disconnect();
    });
